import { sql } from "drizzle-orm";
import { int, sqliteTable, text } from "drizzle-orm/sqlite-core";

export const items = sqliteTable("items", {
  id: int("id").primaryKey({ autoIncrement: true }),
  title: text("title").notNull(),
  createdAt: text("created_at").notNull().default(sql`CURRENT_TIMESTAMP`),
});
import { drizzle } from "drizzle-orm/d1";
import * as schema from "./schema";

export interface CloudflareDatabaseEnv {
  DB: D1Database;
}

// Production data access must go through the D1 binding; do not persist app data on disk.
export function getDb(env: CloudflareDatabaseEnv) {
  return drizzle(env.DB, { schema });
}
interface Env {}

export default {
  async fetch(request) {
    const url = new URL(request.url);

    if (url.pathname === "/api/health") {
      return Response.json({ ok: true });
    }

    if (url.pathname.startsWith("/api/")) {
      return Response.json({ error: "Not found." }, { status: 404 });
    }

    return new Response(null, { status: 404 });
  },
} satisfies ExportedHandler<Env>;
export interface Item {
  createdAt: string;
  id: number;
  title: string;
}

export async function listItems(): Promise<Item[]> {
  const response = await fetch("/api/items");

  if (!response.ok) {
    throw new Error("Unable to load items.");
  }

  return response.json() as Promise<Item[]>;
}

export async function createItem(title: string): Promise<Item> {
  const response = await fetch("/api/items", {
    body: JSON.stringify({ title }),
    headers: {
      "content-type": "application/json",
    },
    method: "POST",
  });

  if (!response.ok) {
    throw new Error("Unable to create item.");
  }

  return response.json() as Promise<Item>;
}
