 {modal==='payment'&&<><div className="modal-icon"><Wallet size={23}/></div><h2>Catat pembayaran SPP</h2><p>Pilih siswa dan bulan tagihan yang akan dilunasi.</p><form onSubmit={pay}><label>Siswa<select value={payStudent} onChange={e=>{setPayStudent(Number(e.target.value));setPayMonths(1)}}>{students.filter(s=>s.months>0&&!s.pending).map(s=><option key={s.id} value={s.id}>{s.name} · {s.className} · {s.months} bulan</option>)}</select></label><div className="form-grid"><label>Jumlah bulan<select value={payMonths} onChange={e=>setPayMonths(Number(e.target.value))}>{Array.from({length:students.find(s=>s.id===payStudent)?.months||1},(_,i)=><option key={i} value={i+1}>{i+1} bulan</option>)}</select></label><label>Metode pembayaran<select value={method} onChange={e=>setMethod(e.target.value)}><option>Tunai</option><option>Transfer</option></select></label></div><label>Tanggal pembayaran<input type="date" name="date" required defaultValue="2026-11-16"/></label>{method==='Transfer'&&<><label>Nama bank<input name="bank" placeholder="Contoh: BSI" required/></label><label>Bukti transfer (JPG, PNG, PDF · maks. 5 MB)<input type="file" name="proof" accept="image/jpeg,image/png,application/pdf" required/></label><div className="notice amber">Transfer menunggu verifikasi dan belum dianggap lunas.</div></>}<label>Catatan<textarea name="notes" placeholder="Catatan pembayaran (opsional)" rows={2}/></label><div className="payment-total"><span>Total pembayaran</span><strong>{money(payMonths*350000)}</strong></div><button className="primary full">Simpan pembayaran<Check size={16}/></button></form></>}
 {modal==='addStudent'&&<><h2>Tambah siswa</h2><p>Lengkapi identitas dan relasi wali murid utama.</p><form onSubmit={e=>{e.preventDefault();const d=new FormData(e.currentTarget);if(students.some(s=>s.nis===d.get('nis'))){notify('NIS sudah digunakan. Gunakan NIS unik.');return}setStudents(ss=>[...ss,{id:Math.max(...ss.map(s=>s.id))+1,nis:String(d.get('nis')),name:String(d.get('name')),className:String(d.get('class')),guardian:String(d.get('guardian')),phone:String(d.get('phone')),months:0,pending:false,dispensation:false,active:true}]);log('Menambah siswa '+d.get('name'));setModal('');notify('Siswa dan wali murid berhasil ditambahkan')} }><label>Nama lengkap<input name="name" required/></label><div className="form-grid"><label>NIS<input name="nis" required/></label><label>Kelas<select name="class">{Array.from({length:12},(_,i)=>`${Math.floor(i/2)+1}${i%2?'B':'A'}`).map(c=><option key={c}>{c}</option>)}</select></label></div><label>Nama wali murid utama<input name="guardian" required/></label><label>WhatsApp wali<input name="phone" pattern="[0-9]{10,15}" placeholder="628..." required/></label><button className="primary full">Simpan siswa</button></form></>}
 {modal==='student'&&selected&&<><div className="row-between"><span className="avatar av1 big">{selected.name.split(' ').slice(0,2).map(n=>n[0]).join('')}</span><Badge tone={selected.months?'amber':'green'}>{eligibility(selected)}</Badge></div><h2>{selected.name}</h2><p>NIS {selected.nis} · Kelas {selected.className} · 2026/2027</p><dl><div><dt>Wali murid</dt><dd>{selected.guardian}</dd></div><div><dt>WhatsApp</dt><dd>{selected.phone}</dd></div><div><dt>Tunggakan</dt><dd>{money(selected.months*350000)} ({selected.months} bulan)</dd></div><div><dt>Risiko</dt><dd>{risk(selected)}</dd></div><div><dt>Status transfer</dt><dd>{selected.pending?'Menunggu verifikasi':'Tidak ada transfer pending'}</dd></div></dl><div className="row-actions"><button className="primary" disabled={selected.months===0||selected.pending} onClick={()=>openPayment(selected)}>Catat pembayaran</button><button className="outline" onClick={()=>reminder(selected)}><MessageCircle size={15}/>Hubungi wali</button></div></>}
 {modal==='generate'&&<><h2>Generate tagihan bulanan</h2><p>Tagihan dibuat untuk siswa aktif. Bulan yang sama tidak dapat diterbitkan dua kali.</p><form onSubmit={e=>{e.preventDefault();const d=new FormData(e.currentTarget);const month=String(d.get('month'));if(generated.includes(month)){notify('Tagihan '+month+' sudah dibuat. Duplikasi dicegah.');return}setGenerated(g=>[...g,month]);setStudents(ss=>ss.map(s=>s.active?{...s,months:s.months+1}:s));log('Generate tagihan '+month);setModal('');notify('Tagihan '+month+' berhasil dibuat untuk siswa aktif.')}}><label>Bulan tagihan<select name="month"><option>November 2026</option><option>Desember 2026</option><option>Januari 2027</option></select></label><div className="payment-total"><span>{students.filter(s=>s.active).length} siswa × {money(amount)}</span><strong>{money(students.filter(s=>s.active).length*amount)}</strong></div><button className="primary full">Generate tagihan</button></form></>}
 {modal==='dispensation'&&<><h2>Ajukan dispensasi</h2><p>Pengajuan TU diteruskan kepada Kepala Sekolah untuk keputusan akhir.</p><form onSubmit={e=>{e.preventDefault();log('Pengajuan dispensasi untuk '+selected?.name);setModal('');notify('Pengajuan dicatat dalam demo. Persetujuan Kepala Sekolah belum diaktifkan.')}}><label>Siswa<select required defaultValue={selected?.id}>{arrears.filter(s=>!s.dispensation).map(s=><option value={s.id} key={s.id}>{s.name} · {s.className}</option>)}</select></label><label>Periode ujian<input value="UAS Semester Ganjil 2026/2027" readOnly/></label><label>Alasan pengajuan<textarea required rows={3}/></label><label>Kemampuan bayar (Rp)<input type="number" required min="0"/></label><label>Tanggal janji bayar<input type="date" required/></label><button className="primary full">Kirim pengajuan<Send size={15}/></button></form></>}
 {modal==='card'&&selected&&<><Brand/><div className="card-heading"><h2>KARTU PESERTA UJIAN</h2><p>UAS Semester Ganjil · 2026/2027</p></div><div className="exam-card-body"><span className="student-photo"><Users size={48}/><small>Foto siswa</small></span><div><h3>{selected.name}</h3><p>NIS: {selected.nis}</p><p>Kelas: {selected.className}</p><strong>UAS26-{selected.className}-{String(selected.id).padStart(3,'0')}</strong></div></div><div className="notice"><TriangleAlert size={18}/>Pratinjau kartu. QR terautentikasi belum diaktifkan.</div><p className="card-date">Pelaksanaan: 7–14 Desember 2026</p><button className="primary full no-print" onClick={()=>{log('Cetak pratinjau kartu '+selected.nis);window.print()}}><Printer size={16}/>Cetak / Simpan PDF</button></>}
 {modal==='addForm'&&<><h2>Buat template karakteristik</h2><form onSubmit={e=>{e.preventDefault();const d=new FormData(e.currentTarget);setForms(f=>[...f,String(d.get('title'))]);setModal('');notify('Template karakteristik berhasil ditambahkan')}}><label>Nama template<input name="title" required/></label><label>Tingkat kelas<select>{[1,2,3,4,5,6].map(i=><option key={i}>Kelas {i}</option>)}</select></label><label>Pertanyaan pertama<input placeholder="Apakah anak menyiapkan perlengkapan sendiri?" required/></label><label>Tipe jawaban<select><option>Ya / Tidak</option><option>Pilihan ganda</option><option>Skala 1–5</option><option>Teks singkat</option><option>Teks panjang</option></select></label><button className="primary full">Simpan template</button></form></>}
 {modal.startsWith('form:')&&<><h2>{forms[Number(modal.split(':')[1])]}</h2><p>Diisi oleh wali murid bersama anak. Batas pengisian 30 November 2026.</p><form onSubmit={e=>{e.preventDefault();log('Menyimpan jawaban karakteristik');setModal('');notify('Jawaban karakteristik dicatat dalam sesi demo')}}><label>Apakah anak menyiapkan perlengkapan sekolah sendiri?<select required><option value="">Pilih jawaban</option><option>Ya</option><option>Tidak</option></select></label><label>Bagaimana anak berinteraksi dengan teman?<select><option>Sangat baik</option><option>Baik</option><option>Perlu pendampingan</option></select></label><label>Kemandirian anak (1–5)<input type="range" min="1" max="5" defaultValue="3"/></label><label>Kebiasaan positif anak<input required/></label><label>Catatan wali murid<textarea rows={3}/></label><button className="primary full">Simpan jawaban</button></form></>}
